<script setup>import{computed,onMounted,ref}from'vue';import{request}from'../api';const data=ref({assets:[],workOrders:[],serviceRequests:[]}),msg=ref('');const waiting=computed(()=>data.value.workOrders.filter(x=>!['CLOSED'].includes(x.status)).length);async function load(){try{data.value=await request('/api/facility-ops/dashboard?organizationCode=ZH-SH')}catch(e){msg.value=e.message}}async function create(){try{await request('/api/facility-ops/assets',{method:'POST',body:JSON.stringify({organizationCode:'ZH-SH',assetNo:'FAC-'+Date.now(),name:'园区冷水机组',location:'A座地下一层机房',criticality:'CRITICAL',warrantyEnd:'2028-12-31'})});msg.value='设施资产已登记，等待管理员启用';await load()}catch(e){msg.value=e.message}}onMounted(load)</script>
<template><section class="head"><div><small>FACILITY OPERATIONS</small><h3>设施运行与维护中心</h3><p>统一管理关键设施、预防性保养、维修工单和服务 SLA。</p></div><button @click="create">登记设施资产</button></section><p class="msg" v-if="msg">{{msg}}</p><section class="metrics"><article><span>设施资产</span><b>{{data.assets.length}}</b><small>在册关键设备</small></article><article><span>执行中工单</span><b>{{waiting}}</b><small>分派、作业、验收</small></article><article><span>SLA 升级</span><b>{{data.serviceRequests.filter(x=>x.escalated).length}}</b><small>需要运营关注</small></article></section><section class="board"><article><header><h4>设施健康台账</h4><button @click="load">刷新</button></header><div class="line" v-for="x in data.assets" :key="x.id"><span class="icon">{{x.criticality==='CRITICAL'?'A':'B'}}</span><div><b>{{x.name}}</b><small>{{x.assetNo}} · {{x.location}}</small></div><em>{{x.status}}</em></div><p v-if="!data.assets.length">暂无专业设施资产。</p></article><article><header><h4>维护工单队列</h4><span>读数防回退</span></header><div class="line" v-for="x in data.workOrders" :key="x.id"><span class="dot"></span><div><b>{{x.workOrderNo}}</b><small>{{x.assignee||'待分派'}} · {{x.dueDate}}</small></div><em>{{x.status}}</em></div><p v-if="!data.workOrders.length">暂无维护工单。</p></article></section></template>
<style scoped>.head{padding:26px 28px;background:linear-gradient(110deg,#123a38,#1d5550);border-radius:14px;color:#fff;display:flex;justify-content:space-between;align-items:end}.head small{letter-spacing:1.5px;color:#9fd1ca}.head h3{font-size:25px;margin:8px 0}.head p{margin:0;color:#d1e5e2}.head button{padding:11px 17px;border:0;border-radius:8px;background:#e6bb68;color:#183a38;font-weight:700}.msg{background:#effaf8;border-left:3px solid #27877e;padding:10px 14px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:16px 0}.metrics article,.board article{background:#fff;border:1px solid #dce7e5;border-radius:12px;padding:18px}.metrics span,.metrics small{display:block;color:#667b78}.metrics b{font-size:29px;display:block;margin:8px 0}.board{display:grid;grid-template-columns:1fr 1fr;gap:16px}.board header,.line{display:flex;align-items:center;justify-content:space-between}.board header{padding-bottom:12px;border-bottom:1px solid #edf3f2}.board header button{border:0;background:transparent;color:#16766d}.line{padding:14px 0;border-bottom:1px solid #edf3f2;gap:10px}.line div{flex:1}.line small{display:block;color:#70817f;margin-top:4px}.line em{font-style:normal;font-size:12px;color:#176c64}.icon{width:30px;height:30px;display:grid;place-items:center;border-radius:8px;background:#d9efeb;color:#16645d;font-weight:800}.dot{width:9px;height:9px;border-radius:50%;background:#dc9c31}@media(max-width:800px){.head{align-items:start;flex-direction:column;gap:20px}.metrics,.board{grid-template-columns:1fr}}</style>
